// Assemble the row + derive storage path from a UUID that the caller may optionally pre-supply.
const crypto = require('crypto');
const uuid   = $json.generation_id || crypto.randomUUID();
const path   = `${$json.user_id}/${uuid}.png`;

return [{
  json: {
    ...$json,
    generation_id:      uuid,
    output_storage_path: path
  },
  binary: $input.item.binary
}];

// Normalise return shape so callers always get generation_id + public output_url.
const row  = Array.isArray($json) ? $json[0] : $json;
const path = row.output_image_path;
const url  = `https://uzghfpxboktnbcbbthns.supabase.co/storage/v1/object/public/${path}`;
return [{ json: {
  generation_id:        row.id,
  user_id:              row.user_id,
  session_id:           row.session_id,
  kind:                 row.kind,
  parent_generation_id: row.parent_generation_id,
  model_id:             row.model_id,
  latency_ms:           row.latency_ms,
  cost_usd:             row.cost_usd,
  room_type:            row.room_type,
  style_tag:            row.style_tag,
  output_url:           url,
  created_at:           row.created_at
} }];
